import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; cut=pd.Timestamp('2027-02-24')
P={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).drop_duplicates('date').set_index('date').sort_index().close.loc[:cut] for s in U}
idx=sorted(set().union(*[set(x.index) for x in P.values()])); p=pd.DataFrame({s:x.reindex(idx) for s,x in P.items()}).ffill(); r=p.pct_change()
# one interpretable candidate: trend / risk, confirmed by recent trend
f=(p.pct_change(60)/(r.rolling(40,min_periods=30).std()*np.sqrt(40)+1e-12))*(.75+.25*np.tanh(p.pct_change(10)*8))
for h in [5,10,20]:
 a=[]; ns=[]; ds=[]
 for i in range(len(p)-h):
  q=pd.concat([f.iloc[i].rename('f'),(p.iloc[i+h]/p.iloc[i]-1).rename('y')],axis=1).dropna()
  if len(q)>=8 and q.f.nunique()>1 and q.y.nunique()>1:
   x=spearmanr(q.f,q.y).statistic
   if np.isfinite(x):a.append(x);ns.append(len(q));ds.append(p.index[i])
 x=np.array(a);print('H',h,'dates',len(x),'avgN',np.mean(ns),'IC',np.mean(x),'ICIR',np.mean(x)/np.std(x,ddof=1),'hit',np.mean(x>0))
 if h==20: print('annual',pd.Series(x,index=ds).groupby(lambda z:z.year).mean().to_dict())
print('coverage',f.notna().mean().mean(),'turn',f.rank(pct=True).diff().abs().mean(axis=1).mean())
# candidate macro-conditioned risk trend: VIX stress downweights trend in stress
v=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).drop_duplicates('date').set_index('date').close.reindex(p.index).ffill(); z=(v-v.rolling(120,min_periods=60).mean())/(v.rolling(120,min_periods=60).std()+1e-12); g=f/(1+z.clip(lower=0))
for h in [10,20]:
 a=[];ns=[]
 for i in range(len(p)-h):
  q=pd.concat([g.iloc[i].rename('f'),(p.iloc[i+h]/p.iloc[i]-1).rename('y')],axis=1).dropna()
  if len(q)>=8 and q.f.nunique()>1 and q.y.nunique()>1:
   a.append(spearmanr(q.f,q.y).statistic);ns.append(len(q))
 x=np.array(a);print('MACRO H',h,'dates',len(x),'avgN',np.mean(ns),'IC',np.mean(x),'ICIR',np.mean(x)/np.std(x,ddof=1),'hit',np.mean(x>0))
print('macro coverage',g.notna().mean().mean(),'turn',g.rank(pct=True).diff().abs().mean(axis=1).mean())

